import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.DnrXFDHb.js";const u=JSON.parse('{"title":"Codex 401 / 403 / 429 怎么排查","description":"Codex 接入 CCWS 后出现 401、403 或 429 时，按 API Key、权限、余额、限流和配置读取顺序排查。","frontmatter":{"title":"Codex 401 / 403 / 429 怎么排查","description":"Codex 接入 CCWS 后出现 401、403 或 429 时，按 API Key、权限、余额、限流和配置读取顺序排查。"},"headers":[],"relativePath":"troubleshooting/codex-error-401-403-429.md","filePath":"troubleshooting/codex-error-401-403-429.md","lastUpdated":1783061751000}'),l={name:"troubleshooting/codex-error-401-403-429.md"};function d(r,e,s,h,n,c){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="codex-401-403-429-怎么排查" tabindex="-1">Codex 401 / 403 / 429 怎么排查 <a class="header-anchor" href="#codex-401-403-429-怎么排查" aria-label="Permalink to &quot;Codex 401 / 403 / 429 怎么排查&quot;">​</a></h1><p>Codex 返回 401、403 或 429 时，先不要反复改 Base URL。Codex 接入 CCWS 的 Base URL 固定是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://www.ccws.pro/v1</span></span></code></pre></div><p>这类错误通常和 API Key、账号权限、额度、限流或工具读取旧配置有关。</p><h2 id="先看错误含义" tabindex="-1">先看错误含义 <a class="header-anchor" href="#先看错误含义" aria-label="Permalink to &quot;先看错误含义&quot;">​</a></h2><table tabindex="0"><thead><tr><th>错误</th><th>常见含义</th><th>优先检查</th></tr></thead><tbody><tr><td>401 Unauthorized</td><td>认证失败</td><td>API Key 是否正确、是否生效、是否被工具读取</td></tr><tr><td>403 Forbidden</td><td>没有权限调用</td><td>账号权限、模型权限、套餐或余额</td></tr><tr><td>429 Too Many Requests</td><td>请求过快或额度受限</td><td>并发、频率、余额、套餐限制</td></tr></tbody></table><h2 id="_401-排查" tabindex="-1">401 排查 <a class="header-anchor" href="#_401-排查" aria-label="Permalink to &quot;401 排查&quot;">​</a></h2><p>按顺序检查：</p><ol><li>当前 Codex 启用的 Provider 是否是 <code>CCWS</code>。</li><li>API Key 是否来自当前 CCWS 账号。</li><li>API Key 是否复制完整，没有多余空格或遗漏字符。</li><li>配置保存后是否重启了 Codex 客户端或终端。</li><li>如果手动配置，<code>auth.json</code> 是否放在用户级 <code>.codex</code> 目录中。</li></ol><p>如果不确定 Key 是否正确，回到 CCWS 控制台重新创建一个 Key，再更新本机配置。</p><h2 id="_403-排查" tabindex="-1">403 排查 <a class="header-anchor" href="#_403-排查" aria-label="Permalink to &quot;403 排查&quot;">​</a></h2><p>403 通常不是网络问题，而是当前账号或 Key 没有权限调用目标模型或接口。</p><p>检查：</p><ul><li>当前账号是否有可用额度。</li><li>当前 Key 是否属于正确账号。</li><li>当前模型名称是否在 CCWS 当前支持范围内。</li><li>如果是团队或分组 Key，确认这个 Key 有调用权限。</li></ul><h2 id="_429-排查" tabindex="-1">429 排查 <a class="header-anchor" href="#_429-排查" aria-label="Permalink to &quot;429 排查&quot;">​</a></h2><p>429 通常表示请求频率、并发或额度受限。</p><p>处理：</p><ul><li>降低并发或减少连续请求。</li><li>等待一段时间后重试。</li><li>检查账号余额或套餐限制。</li><li>如果是多人共用账号，确认是否有其他工具同时调用。</li></ul><h2 id="仍然失败时" tabindex="-1">仍然失败时 <a class="header-anchor" href="#仍然失败时" aria-label="Permalink to &quot;仍然失败时&quot;">​</a></h2><p>联系支持前，请准备：</p><ul><li>出错时间。</li><li>Codex 使用的模型名称。</li><li>完整错误信息截图。</li><li>当前使用的是 CC Switch 还是手动配置。</li><li>不要发送真实 API Key。</li></ul><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="/guide/codex-api-key">Codex API Key 配置</a></li><li><a href="/guide/codex-base-url">Codex Base URL 怎么填</a></li><li><a href="/troubleshooting/auth">认证与 API Key</a></li><li><a href="/troubleshooting/request-error">请求错误</a></li></ul>',23)])])}const x=t(l,[["render",d]]);export{u as __pageData,x as default};
